/* One selected software language shared by every Prediction tab and preview. */
(()=>{'use strict';function init(){const bar=document.querySelector('#prediction .pred-compact-topbar'),source=document.getElementById('setting-language');if(!bar||!source)return false;if(document.getElementById('prediction-quick-language'))return true;const label=document.createElement('label');label.className='prediction-quick-language';label.setAttribute('data-no-localize','');const text=document.createElement('span'),select=document.createElement('select');select.id='prediction-quick-language';select.setAttribute('aria-label','Prediction language');select.replaceChildren(...[...source.options].map(o=>new Option(o.textContent,o.value)));label.append(text,select);bar.prepend(label);function sync(){const language=KPPreferences.get().language;select.value=language;text.textContent=language==='marathi'?'भाषा':language==='hindi'?'भाषा':'Language';select.setAttribute('aria-label',text.textContent);}select.onchange=()=>KPPreferences.save({...KPPreferences.get(),language:select.value});window.addEventListener('kp-preferences-changed',sync);sync();return true;}function start(){if(init())return;const o=new MutationObserver(()=>{if(init())o.disconnect();});o.observe(document.body,{childList:true,subtree:true});}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start);else start();})();
